
const form=document.getElementById('login'),btn=document.getElementById('submit'),msg=document.getElementById('message');
function show(text){msg.textContent=text;msg.classList.add('show')}
form.addEventListener('submit',async e=>{e.preventDefault();msg.classList.remove('show');const email=document.getElementById('email').value.trim(),password=document.getElementById('password').value;if(!email||!password){show('Enter your email and password.');return}btn.disabled=true;btn.textContent='Signing in…';try{const cr=await fetch('/api/auth/csrf',{credentials:'same-origin',cache:'no-store'});if(!cr.ok)throw new Error('Could not start a secure session. Refresh and try again.');const {csrfToken}=await cr.json();const r=await fetch('/api/auth/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},body:JSON.stringify({email,password})});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'Sign-in failed. Check your details and try again.');location.replace('/index.html')}catch(err){show(err.message||'Network error. Please try again.')}finally{btn.disabled=false;btn.textContent='Sign in securely ↗'}});
